50	/// Returns a list of folding ranges for the given file.
51	pub fn folding_ranges(
52	    db: &dyn Db,
53	    file: File,
54	    range_filter: Option<TextRange>,
55	) -> Vec<FoldingRange> {
56	    let parsed = parsed_module(db, file).load(db);
57	    let source = source_text(db, file);
58	
59	    let mut visitor = FoldingRangeVisitor {
60	        source: source.as_str(),
61	        ranges: vec![],
62	        tokens: parsed.tokens(),
63	        range_filter,
64	    };
65	    walk_node(&mut visitor, AnyNodeRef::from(parsed.syntax()));
66	
67	    // Add remaining ranges not covered by the AST visitor.
68	    let own_line_comment_ranges: Vec<_> = parsed
69	        .tokens()
70	        .iter()
71	        .filter_map(|token| {
72	            if token.kind() == TokenKind::Comment
73	                && CommentLinePosition::for_range(token.range(), source.as_str()).is_own_line()
74	            {
75	                Some(TextRange::new(
76	                    source.as_str().line_start(token.start()),
77	                    token.end(),
78	                ))
79	            } else {
80	                None
81	            }
82	        })
83	        .collect();
84	    visitor.add_comment_ranges(&own_line_comment_ranges);
85	    visitor.add_custom_region_ranges(&own_line_comment_ranges);
86	
87	    visitor.ranges
88	}
