24	impl BackgroundDocumentRequestHandler for FoldingRangeRequestHandler {
25	    fn document_url(params: &FoldingRangeParams) -> Cow<'_, Url> {
26	        Cow::Borrowed(&params.text_document.uri)
27	    }
