29	    fn run_with_snapshot(
30	        db: &ProjectDatabase,
31	        snapshot: &DocumentSnapshot,
32	        _client: &Client,
33	        _params: FoldingRangeParams,
34	    ) -> crate::server::Result<Option<Vec<FoldingRange>>> {
35	        if snapshot
36	            .workspace_settings()
37	            .is_language_services_disabled()
38	        {
39	            return Ok(None);
40	        }
41	
42	        let Some(file) = snapshot.to_notebook_or_file(db) else {
43	            return Ok(None);
44	        };
45	
46	        // If this document is a notebook cell, only return folding ranges for this cell.
47	        // Folding ranges are reported as local ranges, so returning notebook-wide ranges
48	        // would produce invalid coordinates for every other cell.
49	        let mut cell_range: Option<TextRange> = None;
50	
51	        if snapshot.document().is_cell()
52	            && let Some(notebook_document) = db.notebook_document(file)
53	            && let Some(notebook) = source_text(db, file).as_notebook()
54	        {
55	            let cell_index = notebook_document.cell_index_by_uri(snapshot.url());
56	            cell_range = cell_index.and_then(|index| notebook.cell_range(index));
